def _github_namespace(repo: Path) -> str:
    """Derive ``github:<owner/repo>`` from the local git remote origin URL."""
    origin = _origin_namespace(Path(repo))
    if origin and origin.startswith("git:") and not origin.startswith("git:local/"):
        return "github:" + origin.removeprefix("git:")
    return f"github:local/{Path(repo).resolve().name}"


def _repository_from_namespace(namespace: str) -> str:
    """Extract ``<owner/repo>`` from a ``github:<owner/repo>`` namespace."""
    if namespace.startswith("github:"):
        return namespace.removeprefix("github:")
    return namespace

